//! 🧱️ Root setters prepare only their authored fields and retain original displaced ownership.
use crate::{LayoutDiff,GridPatch};
use semio_s_artifact_layout_layout_model::{snapshot::LayoutSnapshot,LayoutDrawingMember,GridSettings};
use semio_framework_os_kernel::{ApplyCapability,ArtifactLink,RetainedFieldPreparation};
use semio_framework_value::{RetirementDemand,ValueError,ValueRefusalKind,retained_clone::{RetainedCloneRef,RetainedCloneGrant,RetainedCloneProgress,RetainedCloneStep}};
use super::super::setters::OwnedPatch;
use std::mem::{size_of,ManuallyDrop};
pub struct RootScalars{schema:RetainedFieldPreparation<String>,name:RetainedFieldPreparation<String>,print:RetainedFieldPreparation<Option<String>>,background:RetainedFieldPreparation<Option<LayoutDrawingMember>>,reference:RetainedFieldPreparation<Option<ArtifactLink>>,grid:RetainedFieldPreparation<GridPatch>,grid_value:ManuallyDrop<Option<GridPatch>>,closing:bool}
impl Default for RootScalars{fn default()->Self{Self{schema:Default::default(),name:Default::default(),print:Default::default(),background:Default::default(),reference:Default::default(),grid:Default::default(),grid_value:ManuallyDrop::new(None),closing:false}}}
fn fixed()->RetirementDemand{RetirementDemand{copy_bytes:128,depth:1,..Default::default()}}
fn paid()->RetainedCloneStep{RetainedCloneStep::Complete(RetainedCloneProgress{copied_items:1,copied_bytes:128,..Default::default()})}
fn invalid()->ValueError{ValueError::literal(ValueRefusalKind::InvariantViolated,"Layout root scalar field is invalid")}
fn schema(d:RetainedCloneRef<'_,LayoutDiff>)->RetainedCloneRef<'_,String>{d.project(0,|d|d.schema.as_ref().unwrap())}
fn name(d:RetainedCloneRef<'_,LayoutDiff>)->RetainedCloneRef<'_,String>{d.project(1,|d|d.name.as_ref().unwrap())}
fn grid(d:RetainedCloneRef<'_,LayoutDiff>)->RetainedCloneRef<'_,GridPatch>{d.project(2,|d|d.grid.as_ref().unwrap())}
fn print(d:RetainedCloneRef<'_,LayoutDiff>)->RetainedCloneRef<'_,Option<String>>{d.project(10,|d|&d.print_target.as_ref().unwrap().target)}
fn background(d:RetainedCloneRef<'_,LayoutDiff>)->RetainedCloneRef<'_,Option<LayoutDrawingMember>>{d.project(12,|d|d.background_drawing.as_ref().unwrap())}
fn reference(d:RetainedCloneRef<'_,LayoutDiff>)->RetainedCloneRef<'_,Option<ArtifactLink>>{d.project(14,|d|d.referenced_model.as_ref().unwrap())}
impl RootScalars{
 pub fn supplied(d:&LayoutDiff,index:usize)->bool{match index{0=>d.schema.is_some(),1=>d.name.is_some(),2=>d.print_target.is_some(),3=>d.background_drawing.is_some(),4=>d.referenced_model.is_some(),5..=7=>d.grid.is_some(),_=>false}}
 pub fn ready(&self,index:usize)->bool{match index{0=>self.schema.value().is_some(),1=>self.name.value().is_some(),2=>self.print.value().is_some(),3=>self.background.value().is_some(),4=>self.reference.value().is_some(),5=>self.grid_value.is_some(),_=>false}}
 pub fn preflight_demand(&self,d:RetainedCloneRef<'_,LayoutDiff>,index:usize,body:usize)->Result<RetirementDemand,ValueError>{if !Self::supplied(d.get(),index)||self.ready(index){return Ok(fixed())}match index{0=>self.schema.demand(schema(d),body),1=>self.name.demand(name(d),body),2=>self.print.demand(print(d),body),3=>self.background.demand(background(d),body),4=>self.reference.demand(reference(d),body),5=>if self.grid.value().is_some(){self.grid.exchange_demand()}else{self.grid.demand(grid(d),body)},_=>Err(invalid())}}
 pub fn preflight(&mut self,d:RetainedCloneRef<'_,LayoutDiff>,index:usize,body:usize,g:RetainedCloneGrant)->Result<RetainedCloneStep,ValueError>{let demand=self.preflight_demand(d,index,body)?;if !semio_framework_value::retained_clone::retained_clone_grant_admits(g,demand){return Ok(RetainedCloneStep::Progress(Default::default()))}if !Self::supplied(d.get(),index)||self.ready(index){return Ok(paid())}let step=match index{0=>self.schema.advance(schema(d),body,g)?,1=>self.name.advance(name(d),body,g)?,2=>self.print.advance(print(d),body,g)?,3=>self.background.advance(background(d),body,g)?,4=>self.reference.advance(reference(d),body,g)?,5=>if self.grid.value().is_some(){let(value,p)=self.grid.take(g)?;*self.grid_value=value;RetainedCloneStep::Complete(p)}else{self.grid.advance(grid(d),body,g)?},_=>return Err(invalid())};Ok(if self.ready(index){RetainedCloneStep::Complete(step.progress())}else{RetainedCloneStep::Progress(step.progress())})}
 pub fn commit_demand(&self,d:&LayoutDiff,index:usize)->Result<RetirementDemand,ValueError>{if !Self::supplied(d,index){return Ok(fixed())}match index{0=>self.schema.exchange_demand(),1=>self.name.exchange_demand(),2=>self.print.exchange_demand(),3=>self.background.exchange_demand(),4=>self.reference.exchange_demand(),5..=7=>self.grid_value.as_ref().ok_or_else(invalid)?.field_demand(index-5),_=>Err(invalid())}}
 pub fn commit(&mut self,d:&LayoutDiff,post:&mut LayoutSnapshot,index:usize,g:RetainedCloneGrant,capability:ApplyCapability)->Result<RetainedCloneStep,ValueError>{let demand=self.commit_demand(d,index)?;if !semio_framework_value::retained_clone::retained_clone_grant_admits(g,demand){return Ok(RetainedCloneStep::Progress(Default::default()))}if !Self::supplied(d,index){return Ok(paid())}let p=match index{0=>self.schema.install(&mut post.schema,capability,g)?,1=>self.name.install(&mut post.name,capability,g)?,2=>self.print.install(&mut post.print_target,capability,g)?,3=>self.background.install(&mut post.background_drawing,capability,g)?,4=>self.reference.install(&mut post.referenced_model,capability,g)?,5..=7=>return self.grid_value.as_mut().ok_or_else(invalid)?.exchange_field(&mut post.grid,index-5,g,capability),_=>return Err(invalid())};Ok(RetainedCloneStep::Complete(p))}
 pub fn begin_close(&mut self){self.closing=true;self.schema.begin_close();self.name.begin_close();self.print.begin_close();self.background.begin_close();self.reference.begin_close();self.grid.begin_close()}
 pub fn close_demand(&self,body:usize)->Result<RetirementDemand,ValueError>{if !self.schema.terminal_is_empty(){return self.schema.close_demand(body)}if !self.name.terminal_is_empty(){return self.name.close_demand(body)}if !self.print.terminal_is_empty(){return self.print.close_demand(body)}if !self.background.terminal_is_empty(){return self.background.close_demand(body)}if !self.reference.terminal_is_empty(){return self.reference.close_demand(body)}if !self.grid.terminal_is_empty(){return self.grid.close_demand(body)}if self.grid_value.is_some(){return Ok(RetirementDemand{copy_bytes:size_of::<Option<GridPatch>>()*2,depth:1,..Default::default()})}Ok(Default::default())}
 pub fn close_step(&mut self,g:RetainedCloneGrant)->Result<RetainedCloneStep,ValueError>{if !self.closing{return Err(invalid())}let d=self.close_demand(g.maximum_copy_bytes)?;if !semio_framework_value::retained_clone::retained_clone_grant_admits(g,d){return Ok(RetainedCloneStep::Progress(Default::default()))}if !self.schema.terminal_is_empty(){return self.schema.close_step(g).map(|step|RetainedCloneStep::Progress(step.progress()))}if !self.name.terminal_is_empty(){return self.name.close_step(g).map(|step|RetainedCloneStep::Progress(step.progress()))}if !self.print.terminal_is_empty(){return self.print.close_step(g).map(|step|RetainedCloneStep::Progress(step.progress()))}if !self.background.terminal_is_empty(){return self.background.close_step(g).map(|step|RetainedCloneStep::Progress(step.progress()))}if !self.reference.terminal_is_empty(){return self.reference.close_step(g).map(|step|RetainedCloneStep::Progress(step.progress()))}if !self.grid.terminal_is_empty(){return self.grid.close_step(g).map(|step|RetainedCloneStep::Progress(step.progress()))}if self.grid_value.take().is_some(){return Ok(RetainedCloneStep::Progress(RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,..Default::default()}))}Ok(RetainedCloneStep::Complete(Default::default()))}
 pub fn terminal_is_empty(&self)->bool{self.closing&&self.schema.terminal_is_empty()&&self.name.terminal_is_empty()&&self.print.terminal_is_empty()&&self.background.terminal_is_empty()&&self.reference.terminal_is_empty()&&self.grid.terminal_is_empty()&&self.grid_value.is_none()}
}
impl Drop for RootScalars{fn drop(&mut self){assert!(std::thread::panicking()||self.terminal_is_empty(),"Layout root scalar originals need funded close")}}
